<?php
namespace App\Http\Controllers;
use App\Models\{Attachment,Checklist,CorrectiveAction,Department,Inspection,InspectionResponse,Risk,Setting}; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB;
class InspectionController extends Controller {
 public function index(Request $r){$q=Inspection::with('department','inspector','checklist')->latest('scheduled_at');if($r->user()->hasRole('inspector'))$q->where('inspector_id',$r->user()->id);if($r->user()->hasRole('unit_manager'))$q->where('department_id',$r->user()->department_id);if($r->filled('status'))$q->where('status',$r->status);if($r->filled('q'))$q->where(fn($x)=>$x->where('title','like','%'.$r->q.'%')->orWhere('code','like','%'.$r->q.'%'));return view('inspections.index',['inspections'=>$q->paginate(15)->withQueryString()]);}
 public function create(){return view('inspections.create',['checklists'=>Checklist::where('is_active',true)->get(),'departments'=>Department::where('is_active',true)->get(),'inspectors'=>\App\Models\User::where('role','inspector')->where('is_active',true)->get()]);}
 public function store(Request $r){if($r->filled('scheduled_at'))$r->merge(['scheduled_at'=>optional(jalaliToCarbon($r->input('scheduled_at')))?->toDateTimeString()??$r->input('scheduled_at')]);$d=$r->validate(['title'=>'required|max:190','checklist_id'=>'required|exists:checklists,id','department_id'=>'required|exists:departments,id','inspector_id'=>'required|exists:users,id','scheduled_at'=>'required|date','location'=>'nullable|max:190']);if($r->user()->hasRole('inspector'))$d['inspector_id']=$r->user()->id;$d['code']=$this->code('INS');$i=Inspection::create($d);$this->log('created',$i,'بازرسی جدید برنامه‌ریزی شد.');return redirect()->route('inspections.show',$i)->with('success','بازرسی با موفقیت برنامه‌ریزی شد.');}
 public function show(Inspection $inspection){$u=auth()->user();abort_if($u->hasRole('unit_manager')&&$inspection->department_id!==$u->department_id,403);abort_if($u->hasRole('inspector')&&$inspection->inspector_id!==$u->id,403);$inspection->load('department','inspector','checklist.items','responses.item');return view('inspections.show',compact('inspection'));}
 public function complete(Request $r,Inspection $inspection){abort_unless($r->user()->hasRole(['admin','hse_manager'])||$inspection->inspector_id===$r->user()->id,403);$items=$inspection->checklist->items;$data=$r->validate(['responses'=>'required|array','responses.*.answer'=>'required|in:compliant,noncompliant,na','responses.*.note'=>'nullable|max:2000','responses.*.evidence'=>'nullable|file|max:10240|mimes:jpg,jpeg,png,pdf,doc,docx','responses.*.create_capa'=>'nullable|boolean','responses.*.create_risk'=>'nullable|boolean']);DB::transaction(function()use($inspection,$items,$data,$r){foreach($items as $item){$answer=$data['responses'][$item->id]??null;if(!$answer)continue;$payload=['answer'=>$answer['answer'],'note'=>$answer['note']??null,'is_nonconformity'=>$answer['answer']==='noncompliant'];if($r->hasFile("responses.{$item->id}.evidence"))$payload['evidence_path']=$r->file("responses.{$item->id}.evidence")->store('inspections','public');$response=InspectionResponse::updateOrCreate(['inspection_id'=>$inspection->id,'checklist_item_id'=>$item->id],$payload);if($answer['answer']==='noncompliant'&&!empty($answer['create_risk'])&&!$response->risk_id){$score=$item->is_critical?20:9;$risk=Risk::create(['code'=>$this->code('RSK'),'title'=>'عدم انطباق: '.str($item->question)->limit(140),'description'=>$answer['note']?:$item->question,'category'=>'عدم انطباق بازرسی','department_id'=>$inspection->department_id,'inspection_id'=>$inspection->id,'identified_by'=>$r->user()->id,'owner_id'=>$inspection->department->manager_id,'assessment_method'=>'matrix','likelihood'=>$item->is_critical?4:3,'severity'=>$item->is_critical?5:3,'risk_score'=>$score,'risk_level'=>Risk::level($score),'existing_controls'=>null,'proposed_controls'=>$answer['note']??null,'status'=>'open']);$response->update(['risk_id'=>$risk->id]);}if($answer['answer']==='noncompliant'&&!empty($answer['create_capa'])&&!$response->corrective_action_id){$assignee=$inspection->department->manager_id?:$r->user()->id;$action=CorrectiveAction::create(['code'=>$this->code('ACT'),'title'=>'رفع عدم انطباق: '.str($item->question)->limit(130),'description'=>$answer['note']?:$item->question,'actionable_type'=>$inspection::class,'actionable_id'=>$inspection->id,'department_id'=>$inspection->department_id,'assignee_id'=>$assignee,'assigned_by'=>$r->user()->id,'priority'=>$item->is_critical?'critical':'high','due_date'=>today()->addDays((int)Setting::valueOf('action_reminder_days',7)),'status'=>'assigned']);$response->update(['corrective_action_id'=>$action->id]);}}$valid=$items->whereNotIn('id',collect($data['responses'])->filter(fn($x)=>($x['answer']??'')==='na')->keys())->sum('weight');$earned=$items->filter(fn($i)=>(($data['responses'][$i->id]['answer']??'')==='compliant'))->sum('weight');$inspection->update(['status'=>'completed','started_at'=>$inspection->started_at??now(),'completed_at'=>now(),'score'=>$valid?round($earned/$valid*100,2):100]);});$this->log('completed',$inspection,'بازرسی تکمیل، امتیاز و عدم‌انطباق‌ها ثبت شد.');return back()->with('success','نتایج واقعی بازرسی و موارد پیگیری ثبت شد.');}
}
